import { expr } from './xl/fluent.js'

export class Query {

  // These are required for Peggy Live Preview in VSCode
  /** @private */ get kind() { return this.constructor.name }
  /** @private */ get _() { return this[this.kind] }

  /**
   * Returns the main subject `{ref}` of the query, which refers to the entity being queried or modified.
   * @returns {ref:string[]} The main subject of the query.
   */
  get subject() { return this._.from }

  // Non-enumerable properties that are only valid within the same process
  /** @private */ set source (cql) { Object.defineProperty (this, 'source', { value: cql, writable: true }) }
  /** @private */ set params (arr) { Object.defineProperty (this, 'params', { value: arr, writable: true }) }
  /** @private */ set args (arr)   { Object.defineProperty (this, 'args',   { value: arr, writable: true }) }

  /**
   * - Fills in any binding `{param}`s with corresponding `{val}`s from given `args`.
   * - If no `args` are provided, the ones collected during parsing are used.
   */
  bind (...args) {
    let vals = args?.length ? args : this.args || [], i=0
    if (this.params) for (let p of this.params) {
      if ('list' in p) p.list = vals[i++].map(expr)
      else p.val = vals[i++]
      delete p.param
      delete p.ref
    }
    else !function traverse (cqn) { // for manually created CQNs
      Object.entries (cqn) .forEach (([k,x]) => {
        if (!x || typeof x !== 'object') return
        if (!x.param) return traverse(x)
        let val = vals[i++]; if (val === undefined) return
        let y = cqn[k] = {val}
        if (x.as) y.as = x.as
      })
    } (this)
    return this
  }

  /**
   * - Creates a shallow clone of the given `query`.
   * - Subsequent changes to the clone will not affect the original.
   * - However, changes to nested objects will affect both the original and the clone.
   * @param clauses - Optional list of objects with clauses to override in the clone.
   * @type <T> (this:T, clauses:{columns,from,where,having,groupy,orderBy,limit}[]) => T
   */
  clone (...clauses) {
    const _ = this.kind || Object.keys(this)[0]
    return Object.assign ({ __proto__: this,
      [_]: { __proto__: this[_] }
    }, ...clauses)
  }

  /**
   * Adds the given values to the specified clause in the CQN. If the clause already
   * exists, the new values are appended to the existing ones. Otherwise, a clause
   * is added with the provided values.
   */
  _add (clause, values, former = this._[clause]) {
    if (values === undefined) return this
    this._[clause] = !former ? values : [ ...former, ...values ]
    return this
  }

  /**
   * Sets the specified clause in the CQN to the given value, replacing existing
   * one if present, or overriding it in case of cloned queries.
   */
  _set (clause, value) {
    if (value === undefined) return this
    this._[clause] = value
    return this
  }

  // Custom inspect method to improve the output, e.g. in repl, console.log,
  [Symbol.for('nodejs.util.inspect.custom')] (depth, options, inspect) {
    return `${this.kind} ${inspect(this[this.kind], options)}`
  }
}

/** @private */ Query.for = {} //> filled in from ./index.js
